// @generated by:gauntlet run:godseye-local-infrastructure
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  allocationState,
  desiredInventory,
  fixtureWorkload,
  type InfrastructureFixture,
  infrastructureFixture,
} from "./infra-helpers.js";

describe("transactional isolated cell admission", () => {
  let fixture: InfrastructureFixture;
  beforeEach(async () => {
    fixture = await infrastructureFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });

  it("T-AC-22 T09 runs the actual FoundationEngine consumer and verifies effective policy before starting", async () => {
    const { allocation } = await fixture.admit();
    expect(allocation.state).toBe("reserved");
    expect(fixture.provider.effects).toHaveLength(0);

    await fixture.infrastructure.foundation.tick("infrastructure-fixture-worker");

    expect(await allocationState(fixture, allocation.id)).toMatchObject({ state: "verified" });
    expect(fixture.provider.effects.map(({ action }) => action)).toEqual([
      "network",
      "firewall",
      "data",
      "sandbox",
      "start",
    ]);
    if (!allocation.runId) throw new Error("Admitted fixture run missing");
    expect(
      await fixture.infrastructure.foundation.getRun(fixture.freshOwner(), allocation.runId),
    ).toMatchObject({ status: "succeeded" });
    expect(await fixture.infrastructure.foundation.tick("infrastructure-fixture-worker")).toBe(
      false,
    );
  });

  it("T-AC-21 T37 converges concurrent identical admission without duplicate physical allocation or provider effects", async () => {
    const preparation = await fixture.prepare();
    const key = randomUUID();
    const input = { preparationId: preparation.id, expectedHash: preparation.hash };

    const accepted = await Promise.all([
      fixture.infrastructure.admit(fixture.freshOwner(), input, key),
      fixture.infrastructure.admit(fixture.freshOwner(), input, key),
    ]);

    expect(accepted[0]?.id).toBe(accepted[1]?.id);
    expect((await fixture.infrastructure.overview(fixture.freshOwner())).allocations).toHaveLength(
      1,
    );
    await fixture.infrastructure.foundation.tick("infrastructure-fixture-worker");
    expect(fixture.provider.effects.filter(({ action }) => action === "start")).toHaveLength(1);
    await expect(
      fixture.infrastructure.admit(
        fixture.freshOwner(),
        { ...input, expectedHash: "b".repeat(64) },
        key,
      ),
    ).rejects.toMatchObject({ status: 409 });
  });

  it("T-AC-21 T05 admits at most one competing CPU reservation across different environments", async () => {
    const prior = await fixture.infrastructure.overview(fixture.freshOwner());
    const desired = desiredInventory();
    desired.expectedRevision = prior.revision;
    desired.pool.capacity.cpuMilliCores = 1000;
    desired.pool.headroom.cpuMilliCores = 100;
    await fixture.infrastructure.declareInventory(fixture.freshOwner(), desired, randomUUID());
    const preparations = await Promise.all([
      fixture.prepare({ ...fixtureWorkload, cpuMilliCores: 600 }, fixture.development.id),
      fixture.prepare({ ...fixtureWorkload, cpuMilliCores: 600 }, fixture.production.id),
    ]);

    const results = await Promise.allSettled(
      preparations.map((preparation) =>
        fixture.infrastructure.admit(
          fixture.freshOwner(),
          { preparationId: preparation.id, expectedHash: preparation.hash },
          randomUUID(),
        ),
      ),
    );

    expect(results.filter(({ status }) => status === "fulfilled")).toHaveLength(1);
    expect(results.filter(({ status }) => status === "rejected")).toHaveLength(1);
    expect((await fixture.infrastructure.overview(fixture.freshOwner())).allocations).toHaveLength(
      1,
    );
    expect(fixture.provider.effects).toHaveLength(0);
  });

  it("T-AC-21 T09 forbids two ordinary active allocations for one logical environment", async () => {
    const preparations = await Promise.all([fixture.prepare(), fixture.prepare()]);
    const results = await Promise.allSettled(
      preparations.map((preparation) =>
        fixture.infrastructure.admit(
          fixture.freshOwner(),
          { preparationId: preparation.id, expectedHash: preparation.hash },
          randomUUID(),
        ),
      ),
    );

    expect(results.filter(({ status }) => status === "fulfilled")).toHaveLength(1);
    expect((await fixture.infrastructure.overview(fixture.freshOwner())).allocations).toHaveLength(
      1,
    );
    await fixture.infrastructure.foundation.tick("infrastructure-fixture-worker");
    const refused = preparations.find(
      (preparation) =>
        preparation.allocationId !==
        (
          results.find(({ status }) => status === "fulfilled") as
            | PromiseFulfilledResult<{ id: string }>
            | undefined
        )?.value.id,
    );
    if (!refused) throw new Error("Competing fixture preparation missing");
    await expect(
      fixture.infrastructure.admit(
        fixture.freshOwner(),
        { preparationId: refused.id, expectedHash: refused.hash },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    expect(fixture.provider.effects.filter(({ action }) => action === "start")).toHaveLength(1);
  });

  it("T-AC-21 T05 preserves host headroom without double counting cells inside the professional VM", async () => {
    const desired = desiredInventory();
    const professional = desired.guests.find(({ role }) => role === "professional");
    const games = desired.guests.find(({ role }) => role === "games");
    if (!professional || !games) throw new Error("Fixture guest topology incomplete");
    desired.expectedRevision = 1;
    desired.host.capacity.memoryMiB =
      desired.host.headroom.memoryMiB + professional.capacity.memoryMiB + games.capacity.memoryMiB;
    fixture.collector.observation.hostCapacity = structuredClone(desired.host.capacity);
    await fixture.infrastructure.declareInventory(fixture.freshOwner(), desired, randomUUID());
    await fixture.infrastructure.refreshInventory(
      fixture.freshOwner(),
      { expectedRevision: 1 },
      randomUUID(),
    );

    const { allocation } = await fixture.admit();

    expect(allocation.state).toBe("reserved");
    expect(fixture.provider.effects).toHaveLength(0);
  });

  it("T-AC-21 T05 counts temporary memory with application memory rather than admitting it for free", async () => {
    const desired = desiredInventory();
    desired.expectedRevision = 1;
    desired.pool.capacity.memoryMiB = 200;
    desired.pool.headroom.memoryMiB = 64;
    await fixture.infrastructure.declareInventory(fixture.freshOwner(), desired, randomUUID());
    const preparation = await fixture.prepare({
      ...fixtureWorkload,
      memoryMiB: 128,
      temporaryMiB: 16,
    });

    await expect(
      fixture.infrastructure.admit(
        fixture.freshOwner(),
        { preparationId: preparation.id, expectedHash: preparation.hash },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    expect((await fixture.infrastructure.overview(fixture.freshOwner())).allocations).toHaveLength(
      0,
    );
  });
});
